ed","cyan_bed","yellow_bed","light_blue_bed","white_bed","acacia_door","white_concrete","glass_pane","mud_bricks","mud_brick_slab","smooth_stone_slab","water","light_blue_concrete","smooth_quartz_slab"]}// Runs every vocabulary share's test
import { execFileSync } from "node:child_process";
